import React, { useState, useEffect } from 'react';
import { useSelector } from 'react-redux';
import {
  Box,
  Container,
  Grid,
  Card,
  CardContent,
  Typography,
  Button,
  Fab,
  AppBar,
  Toolbar,
  IconButton,
  Badge,
} from '@mui/material';
import {
  Emergency,
  LocationOn,
  Chat,
  History,
  Settings,
  Notifications,
  Menu,
  Person,
} from '@mui/icons-material';

const Dashboard = () => {
  const { user } = useSelector((state) => state.auth);
  const [currentLocation, setCurrentLocation] = useState(null);

  useEffect(() => {
    // Get current location
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(
        (position) => {
          setCurrentLocation({
            latitude: position.coords.latitude,
            longitude: position.coords.longitude,
          });
        },
        (error) => {
          console.error('Location error:', error);
        }
      );
    }
  }, []);

  const handleEmergencyAlert = () => {
    alert('Emergency Alert Sent!');
  };

  const quickActions = [
    { icon: <Chat />, label: 'AI Assistant', path: '/chat' },
    { icon: <History />, label: 'Alert History', path: '/alert-history' },
    { icon: <Person />, label: 'Emergency Contacts', path: '/emergency-contacts' },
    { icon: <Settings />, label: 'Settings', path: '/settings' },
  ];

  return (
    <Box>
      {/* App Bar */}
      <AppBar position="static" elevation={0}>
        <Toolbar>
          <Typography variant="h6" component="div" sx={{ flexGrow: 1 }}>
            Welcome, {user?.fullName?.split(' ')[0] || 'User'}
          </Typography>
          <IconButton color="inherit">
            <Badge badgeContent={0} color="error">
              <Notifications />
            </Badge>
          </IconButton>
          <IconButton color="inherit">
            <Menu />
          </IconButton>
        </Toolbar>
      </AppBar>

      <Container maxWidth="lg" sx={{ py: 3 }}>
        <Grid container spacing={3}>
          {/* Emergency Button */}
          <Grid item xs={12}>
            <Card sx={{ textAlign: 'center', py: 4, background: 'linear-gradient(135deg, #ff6b9d 0%, #c53975 100%)' }}>
              <CardContent>
                <Typography variant="h5" color="white" mb={3}>
                  Emergency SOS
                </Typography>
                <Fab
                  onClick={handleEmergencyAlert}
                  sx={{
                    width: 120,
                    height: 120,
                    background: 'linear-gradient(135deg, #ff416c 0%, #ff4b2b 100%)',
                    color: 'white',
                    '&:hover': {
                      background: 'linear-gradient(135deg, #ff416c 0%, #ff4b2b 100%)',
                      transform: 'scale(1.05)',
                    },
                  }}
                >
                  <Emergency sx={{ fontSize: 40 }} />
                </Fab>
                <Typography variant="body2" color="white" mt={2}>
                  Tap for Emergency
                </Typography>
              </CardContent>
            </Card>
          </Grid>

          {/* Location Display */}
          <Grid item xs={12} md={8}>
            <Card>
              <CardContent>
                <Typography variant="h6" mb={2}>
                  <LocationOn color="primary" sx={{ mr: 1, verticalAlign: 'middle' }} />
                  Your Location
                </Typography>
                <Box
                  display="flex"
                  justifyContent="center"
                  alignItems="center"
                  height={300}
                  bgcolor="grey.100"
                  borderRadius={2}
                >
                  {currentLocation ? (
                    <Box textAlign="center">
                      <LocationOn color="primary" sx={{ fontSize: 40, mb: 1 }} />
                      <Typography variant="h6">Location Found</Typography>
                      <Typography variant="body2" color="text.secondary">
                        Lat: {currentLocation.latitude.toFixed(4)}<br/>
                        Lng: {currentLocation.longitude.toFixed(4)}
                      </Typography>
                    </Box>
                  ) : (
                    <Box textAlign="center">
                      <LocationOn color="disabled" sx={{ fontSize: 40, mb: 1 }} />
                      <Typography color="text.secondary">
                        Getting your location...
                      </Typography>
                    </Box>
                  )}
                </Box>
              </CardContent>
            </Card>
          </Grid>

          {/* Quick Actions */}
          <Grid item xs={12} md={4}>
            <Card>
              <CardContent>
                <Typography variant="h6" mb={2}>
                  Quick Actions
                </Typography>
                <Grid container spacing={2}>
                  {quickActions.map((action, index) => (
                    <Grid item xs={6} key={index}>
                      <Button
                        fullWidth
                        variant="outlined"
                        startIcon={action.icon}
                        onClick={() => window.location.href = action.path}
                        sx={{ py: 2, flexDirection: 'column', gap: 1 }}
                      >
                        {action.label}
                      </Button>
                    </Grid>
                  ))}
                </Grid>
              </CardContent>
            </Card>
          </Grid>

          {/* Safety Tips */}
          <Grid item xs={12}>
            <Card>
              <CardContent>
                <Typography variant="h6" mb={2}>
                  Daily Safety Tips
                </Typography>
                <Typography variant="body2" color="text.secondary">
                  • Always share your location with trusted contacts when going out<br/>
                  • Trust your instincts - if something feels wrong, seek help immediately<br/>
                  • Keep your phone charged and emergency contacts updated<br/>
                  • Use well-lit and populated routes when walking alone<br/>
                  • Consider using the NIVRA AI assistant for safety guidance
                </Typography>
              </CardContent>
            </Card>
          </Grid>
        </Grid>
      </Container>
    </Box>
  );
};

export default Dashboard;
